/**
 * Service-worker registration with `workbox-window` (the worker itself is generated by vite-plugin-pwa with
 * `registerType: 'prompt'`, see `pwa.config.ts`). Only production builds register it; the dev server and unit tests
 * have no worker. A new version waits until the learner accepts the update prompt; then the waiting worker is told
 * to skip waiting and the page reloads once it controls the page.
 */

/** Callbacks of the registration. */
export interface ServiceWorkerHandlers {
  /** A new version is installed and waiting – show "Neue Version verfügbar". */
  onNeedRefresh: () => void;
}

/** Activates the waiting worker; the page reloads when it takes control. */
export type ApplyUpdate = () => Promise<void>;

/** Path of the generated worker below the app's base URL. */
export const SERVICE_WORKER_FILE = 'sw.js';

/** Registers the service worker (only in production builds and only where supported). */
export async function registerServiceWorker(handlers: ServiceWorkerHandlers): Promise<ApplyUpdate | null> {
  if (!import.meta.env.PROD || typeof navigator === 'undefined' || !('serviceWorker' in navigator)) return null;
  const { Workbox } = await import('workbox-window');
  const base = import.meta.env.BASE_URL;
  const wb = new Workbox(`${base}${SERVICE_WORKER_FILE}`, { scope: base });
  let reloading = false;
  wb.addEventListener('waiting', () => handlers.onNeedRefresh());
  await wb.register({ immediate: true });
  return async () => {
    wb.addEventListener('controlling', () => {
      if (reloading) return;
      reloading = true;
      window.location.reload();
    });
    wb.messageSkipWaiting();
  };
}
